begin;
select no_plan();
create function pg_temp.ai_id(n integer) returns uuid language sql immutable as $$select ('ac030000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ai_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-key-'||n||'@test.invalid' from generate_series(1,3) n;
insert into public.profiles(id,role,name) select pg_temp.ai_id(n),case when n in(1,3) then 'admin' else 'staff' end,'AI key fixture' from generate_series(1,3) n on conflict(id) do update set role=excluded.role;
create temp table ev(k text primary key,v jsonb);
grant all on ev to authenticated,service_role;
insert into dashboard_private.agent_credentials(created_by,label,token_hash,scopes,class_ids,expires_at) values(pg_temp.ai_id(1),'synthetic existing class key',repeat('b',64),array['classes:read'],'{}',clock_timestamp()+interval '1 day');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{"queues":["employee_requests"],"actions":["read"]}',null)$q$,'42501','ai_agent_forbidden','staff cannot issue');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['classes:read'],'{"queues":["employee_requests"],"actions":["read"]}',null)$q$,'22023','ai_agent_invalid','class scopes cannot become AI authority');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{"queues":["all"],"actions":["read"]}',null)$q$,'22023','ai_agent_invalid','unapproved queue rejected');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{}',null)$q$,'22023','ai_agent_invalid','explicit resource grant required');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['chat:send'],'{"spaceKeys":["unknown"],"purposes":["ai_completion"]}',null)$q$,'22023','ai_agent_invalid','uncatalogued Chat space denied');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['chat:send'],'{"spaceKeys":["space_1"],"purposes":["arbitrary"]}',null)$q$,'22023','ai_agent_invalid','uncatalogued Chat purpose denied');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['chat:send'],'{"spaceKeys":["space_1"],"purposes":["bridge_reply"]}',null)$q$,'22023','ai_agent_invalid','bridge grant requires stable source ID');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{"queues":["employee_requests"],"actions":["read"]}',now()+interval '31 days')$q$,'22023','ai_agent_invalid','expiry maximum enforced');
-- Synthetic issuance is transaction-local in the disposable test DB only.
insert into ev values('read',public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{"queues":["employee_requests"],"actions":["read"]}',null));
select ok((select v->>'token' ~ '^tips_agent_[a-f0-9]{64}$' from ev where k='read'),'issuer response is sole raw-token response');
select ok(public.list_ai_agent_credentials_v1(1,10)::text not like '%tips_agent_%','inventory contains no raw token');
select ok(not(public.list_ai_agent_credentials_v1(1,10)->'items'->0 ? 'tokenHash'),'inventory contains no hash');
select ok((select (v->>'expiresAt')::timestamptz between clock_timestamp()+interval '23 hours' and clock_timestamp()+interval '25 hours' from ev where k='read'),'default credential lifetime is one day');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('a',64),'list','{}')$q$,'42501',null,'authenticated cannot execute bot gateway');
reset role;
create function pg_temp.ai_bot(a text,i jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_bot_api_v1(encode(sha256(convert_to((select v->>'token' from ev where k='read'),'UTF8')),'hex'),a,i)$$;
set local role service_role;
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('a',64),'list','{}')$q$,'28000','ai_agent_unauthorized','unknown/class store credential rejected');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('b',64),'list','{}')$q$,'28000','ai_agent_unauthorized','real synthetic class store key cannot authenticate AI gateway');
select lives_ok($q$select pg_temp.ai_bot('list')$q$,'granted AI read accepted');
select throws_ok($q$select pg_temp.ai_bot('claim')$q$,'42501','ai_agent_scope_forbidden','unapproved bot action rejected');
select throws_ok($q$select pg_temp.ai_bot('list','{"page":1}')$q$,'22023','ai_agent_invalid','bot cannot mix employee paging');
select throws_ok($q$select pg_temp.ai_bot('list','{"limit":51}')$q$,'22023','ai_agent_invalid','bot limit bounded at fifty');
select throws_ok($q$select * from dashboard_private.ai_agent_credentials$q$,'42501',null,'service_role cannot read private hashes');
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{}',null)$q$,'42501',null,'service_role cannot issue');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);
set local role authenticated;
select is(public.list_ai_agent_credentials_v1(1,10)->>'total','0','inventory issuer isolated');
select throws_ok($q$select public.revoke_ai_agent_credential_v1((select (v->>'id')::uuid from ev where k='read'))$q$,'P0002','ai_agent_not_found','other admin cannot revoke issuer credential');
reset role;
update dashboard_private.ai_agent_credentials set rate_window=date_trunc('minute',clock_timestamp()),rate_count=60;
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'54000','ai_agent_rate_limited','bot sixty-per-minute budget enforced');
reset role;
update dashboard_private.ai_agent_credentials set rate_count=0;
update public.profiles set role='staff' where id=pg_temp.ai_id(1);
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'42501','ai_agent_forbidden','issuer role loss rejected');
reset role;
update public.profiles set role='admin' where id=pg_temp.ai_id(1);
update dashboard_private.ai_agent_credentials set expires_at=clock_timestamp()-interval '1 second';
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'28000','ai_agent_unauthorized','expired bot rejected');
reset role;
update dashboard_private.ai_agent_credentials set expires_at=clock_timestamp()+interval '1 day';
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select public.revoke_ai_agent_credential_v1((select (v->>'id')::uuid from ev where k='read'));
reset role;
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'28000','ai_agent_unauthorized','revoked bot rejected');
reset role;
update dashboard_private.ai_agent_credentials set revoked_at=null;
update dashboard_private.ai_agent_credential_grants set revoked_at=null,expires_at=clock_timestamp()-interval '1 second';
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'42501','ai_agent_grant_forbidden','expired purpose grant denied independently');
reset role;
update dashboard_private.ai_agent_credential_grants set expires_at=clock_timestamp()+interval '1 day',revoked_at=clock_timestamp();
set local role service_role;
select throws_ok($q$select pg_temp.ai_bot('list')$q$,'42501','ai_agent_grant_forbidden','revoked purpose grant denied independently');
reset role;
select ok(not exists(select 1 from information_schema.columns where table_schema='dashboard_private' and table_name in('ai_agent_credentials','ai_agent_credential_grants','chat_credential_space_grants') and column_name in('token','raw_token')),'raw token has no storage column');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) role_name cross join unnest(array['ai_agent_credentials','ai_agent_credential_grants','chat_credential_space_grants','chat_user_space_permissions']) table_name where has_table_privilege(role_name,'dashboard_private.'||table_name,'SELECT,INSERT,UPDATE,DELETE')),'every private credential and grant table denies direct access');
insert into dashboard_private.ai_agent_credentials(created_by,label,token_hash,scopes,expires_at) select pg_temp.ai_id(1),'synthetic cap fixture',encode(sha256(convert_to('synthetic-cap-'||n,'UTF8')),'hex'),array['ai-agent:requests:read'],clock_timestamp()+interval '1 day' from generate_series(1,19) n;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select throws_ok($q$select public.create_ai_agent_credential_v1('synthetic',array['ai-agent:requests:read'],'{"queues":["employee_requests"],"actions":["read"]}',null)$q$,'54000','ai_agent_credential_limit','twenty active credentials maximum');
reset role;
select ok((select bool_and(relrowsecurity) from pg_class where oid in('dashboard_private.ai_agent_credentials'::regclass,'dashboard_private.ai_agent_credential_grants'::regclass,'dashboard_private.chat_credential_space_grants'::regclass,'dashboard_private.chat_user_space_permissions'::regclass)),'credential and grant stores enable RLS');
select * from finish();
rollback;
